import{af as t,z as r,J as a,ab as o}from"./chunks/framework.C1QHhBQn.js";const p=JSON.parse('{"title":"LED guide","description":"","frontmatter":{"aside":true,"order":1},"headers":[],"relativePath":"guides/leds.md","filePath":"guides/leds.md"}'),i={name:"guides/leds.md"};function d(n,e,s,l,h,c){return r(),a("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794235425000"},[...e[0]||(e[0]=[o('<h1 id="led-guide" tabindex="-1">LED guide <a class="header-anchor" href="#led-guide" aria-label="Permalink to &quot;LED guide&quot;">​</a></h1><p><strong>Start with your device model, not the colour of a light.</strong> ProN (PR2) and Pro3 (PR3) look alike but have different LED hardware. Zero ZE2 and ZE3 are also different generations.</p><p>Check the product code on the label or in your device details. The device ID prefix can help identify the family. If you are unsure, <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">contact support</a> with the device ID rather than selecting a guide by appearance alone.</p><h2 id="choose-your-model" tabindex="-1">Choose your model <a class="header-anchor" href="#choose-your-model" aria-label="Permalink to &quot;Choose your model&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Device</th><th>How to identify it</th><th>Matching LED guide</th></tr></thead><tbody><tr><td>Pro3 / PR3</td><td>Prefix 52; four orange indicators on revisions 02–04</td><td><a href="/docs/pr/40/guides/pro3-leds">Pro3 battery, charging and restart patterns</a></td></tr><tr><td>ProN / PR2 (legacy)</td><td>Prefix 20; four battery indicators plus GPS/mobile diagnostics</td><td><a href="/docs/pr/40/guides/tracker-leds#pro-pr2">ProN / PR2</a></td></tr><tr><td>Zero / ZE2 / ZeroN</td><td>Prefix 19; four battery indicators plus GPS/mobile diagnostics</td><td><a href="/docs/pr/40/guides/tracker-leds#zero-ze2">Zero ZE2</a></td></tr><tr><td>Enviro / EN2 / EnviroN</td><td>Prefix 26; four battery indicators plus GPS/mobile diagnostics</td><td><a href="/docs/pr/40/guides/tracker-leds#enviro-en2">Enviro EN2</a></td></tr><tr><td>Vehicle / VT3</td><td>Prefix 40; four indicators</td><td><a href="/docs/pr/40/guides/vehicle-leds">Vehicle battery, ignition and charging patterns</a></td></tr><tr><td>Handheld RTK / RH2</td><td>RH2 product code; RGB status display and application-controlled lights</td><td><a href="/docs/pr/40/guides/rtk-leds#handheld-rtk-rh2">RH2 RGB status and application feedback</a></td></tr><tr><td>Vehicle RTK / VTRTK</td><td>Vehicle RTK product code; four indicators</td><td><a href="/docs/pr/40/guides/rtk-leds#vehicle-rtk-vtrtk">VTRTK battery and ignition display</a></td></tr><tr><td>Zero3 / ZE3</td><td>Prefix 49; four orange indicators on revision 01</td><td><a href="/docs/pr/40/guides/ze3-leds">ZE3 revision-specific guidance</a></td></tr></tbody></table><p>For VT2, RH1 or another earlier model, use its <a href="/docs/pr/40/devices/history/">legacy device documentation</a> or ask support. Custom devices and applications can have their own LED meanings. Do not apply the table for a similar-looking model.</p><h2 id="identify-what-is-happening" tabindex="-1">Identify what is happening <a class="header-anchor" href="#identify-what-is-happening" aria-label="Permalink to &quot;Identify what is happening&quot;">​</a></h2><ol><li><strong>Just started or restarted?</strong> Wait for startup to finish. A startup pattern is not a battery measurement or a fault code by itself.</li><li><strong>Connected to power?</strong> Use the matching charging section. Charging, external power and ignition are different states on vehicle trackers.</li><li><strong>Pressed a button?</strong> The device may briefly show battery or connection information and then go dark.</li><li><strong>Running an application or alarm?</strong> Its feedback can override the standard display. For example, the RH2 Survey application&#39;s green/red flashes describe point submission, not the normal charge level.</li></ol><p>No lights does not necessarily mean that a tracker is off. Many devices turn their lights off while resting to save power. A coloured light also does not prove that a new location has reached the server: check the latest successful communication in the app or portal.</p><h2 id="restart-and-troubleshooting" tabindex="-1">Restart and troubleshooting <a class="header-anchor" href="#restart-and-troubleshooting" aria-label="Permalink to &quot;Restart and troubleshooting&quot;">​</a></h2><p>On the older ProN/PR2, <a href="/docs/pr/40/guides/tracker-leds#two-red-lights-and-four-orange-lights-after-a-restart">two red lights and four orange lights can appear during a restart</a>. This is not the Pro3 layout, and it is not a universal Lightbug fault code.</p><p>Avoid repeatedly resetting a tracker based on its lights alone. If updates do not resume, follow <a href="/docs/pr/40/faq/troubleshooting#why-is-my-tracker-not-transmitting">tracker troubleshooting</a>. If a restart is needed, use the <a href="/docs/pr/40/faq/troubleshooting#restarting-a-tracker">model and firmware guidance</a>, rather than a universal button duration or beep sequence.</p><h2 id="when-to-contact-support" tabindex="-1">When to contact support <a class="header-anchor" href="#when-to-contact-support" aria-label="Permalink to &quot;When to contact support&quot;">​</a></h2><p>If a pattern persists, charging does not progress, or the device stops communicating, include:</p><ul><li>Product code and device ID, plus hardware/firmware revision if known.</li><li>Whether it is charging, has external power, or has just restarted.</li><li>The latest successful communication time from the app or portal.</li><li>A short video showing the order, colour and timing of the lights.</li></ul><p>This guide covers normal device operation. Manufacturing tests, bootloader recovery and custom applications have separate instructions; their LED codes should not be used to diagnose a tracker in ordinary service.</p>',16)])])}const g=t(i,[["render",d]]);export{p as __pageData,g as default};
